import cors from "cors";
import express from "express";

const ALLOWED_ORIGINS = ["http://localhost:3000", "https://app.example.com"];
const ALLOWED_PATTERNS = [/^https:\/\/[a-z0-9-]+\.preview\.example\.com$/];
const isAllowedOrigin = (origin: string) =>
  ALLOWED_ORIGINS.includes(origin) || ALLOWED_PATTERNS.some(p => p.test(origin));

const app = express();
app.use(cors({
  origin: (origin, callback) => {
    // Requests without an Origin header (curl, mobile apps, server-to-server) are not CORS requests.
    if (!origin || isAllowedOrigin(origin)) return callback(null, true);
    callback(new Error(`Origin ${origin} is not allowed by CORS`));
  },
  methods: ["GET","POST","PUT","PATCH","DELETE"],
  allowedHeaders: ["Content-Type","Authorization","X-Request-Id"],
  exposedHeaders: ["X-Total-Count"],
  credentials: true,
  maxAge: 600,
}));

