import { NextRequest, NextResponse } from "next/server";

const ALLOWED_ORIGINS = ["http://localhost:3000", "https://app.example.com"];
const ALLOWED_PATTERNS = [/^https:\/\/[a-z0-9-]+\.preview\.example\.com$/];
const isAllowedOrigin = (origin: string) =>
  ALLOWED_ORIGINS.includes(origin) || ALLOWED_PATTERNS.some(p => p.test(origin));

const CORS_HEADERS: Record<string, string> = {
  "Access-Control-Allow-Methods": "GET,POST,PUT,PATCH,DELETE",
  "Access-Control-Allow-Headers": "Content-Type,Authorization,X-Request-Id",
  "Access-Control-Expose-Headers": "X-Total-Count",
  "Access-Control-Allow-Credentials": "true",
  "Access-Control-Max-Age": "600",
};

export function middleware(request: NextRequest) {
  const origin = request.headers.get("origin") ?? "";
  const allowed = origin !== "" && isAllowedOrigin(origin);

  if (request.method === "OPTIONS") {
    // Preflight: answer directly with 204.
    return new NextResponse(null, {
      status: 204,
      headers: allowed ? { ...CORS_HEADERS, "Access-Control-Allow-Origin": origin, Vary: "Origin" } : {},
    });
  }

  const response = NextResponse.next();
  if (allowed) {
    response.headers.set("Access-Control-Allow-Origin", origin);
    response.headers.set("Vary", "Origin");
    for (const [key, value] of Object.entries(CORS_HEADERS)) response.headers.set(key, value);
  }
  return response;
}

