import { z } from "zod";

export const createProductSchema = z.object({
  name: z.string().trim().min(1).max(255),
  slug: z.string().trim().min(1).max(255),
  description: z.string().max(10000).optional(),
  price: z.number(),
  stock: z.number().int(),
  status: z.enum(["draft", "active", "archived"]),
  tags: z.array(z.string()).optional(),
  imageUrl: z.string().url().optional(),
});

export const updateProductSchema = createProductSchema.partial();

export const listProductQuerySchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

export type CreateProductInput = z.infer<typeof createProductSchema>;
export type UpdateProductInput = z.infer<typeof updateProductSchema>;

export interface Product {
  id: string;
  name: string;
  slug: string;
  description?: string;
  price: number;
  stock: number;
  status: "draft" | "active" | "archived";
  tags?: string[];
  imageUrl?: string;
  createdAt: Date;
  updatedAt: Date;
}

import { PrismaClient } from "@prisma/client";

// One client per process; reuse it across hot reloads in development.
const globalForPrisma = globalThis as unknown as { prisma?: PrismaClient };
export const prisma = globalForPrisma.prisma ?? new PrismaClient();
if (process.env.NODE_ENV !== "production") globalForPrisma.prisma = prisma;

import { Prisma } from "@prisma/client";
import { prisma } from "../prisma";
import { CreateProductInput, UpdateProductInput } from "./product.schema";

export function listProducts(skip: number, take: number) {
  return prisma.product.findMany({ skip, take, orderBy: { createdAt: "desc" } });
}

export function countProducts() {
  return prisma.product.count();
}

export function getProduct(id: string) {
  return prisma.product.findUnique({ where: { id } });
}

export function createProduct(input: CreateProductInput) {
  return prisma.product.create({ data: input as Prisma.ProductCreateInput });
}

export async function updateProduct(id: string, input: UpdateProductInput) {
  try {
    return await prisma.product.update({ where: { id }, data: input as Prisma.ProductUpdateInput });
  } catch (error) {
    // P2025: record to update not found
    if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === "P2025") return null;
    throw error;
  }
}

export async function deleteProduct(id: string) {
  const { count } = await prisma.product.deleteMany({ where: { id } });
  return count > 0;
}

