// Express 4 does not catch rejected promises; this forwards them to the error handler.
const handle = (fn: (req: Request, res: Response) => Promise<unknown>) =>
  (req: Request, res: Response, next: NextFunction) => fn(req, res).catch(next);

productsRouter.get("/", handle(async (req, res) => {
  const { page, limit } = listProductQuerySchema.parse(req.query);
  const [items, total] = await Promise.all([repo.listProducts((page - 1) * limit, limit), repo.countProducts()]);
  res.json({ items, page, limit, total, pages: Math.ceil(total / limit) });
}));

productsRouter.get("/:id", handle(async (req, res) => {
  const item = await repo.getProduct(req.params.id);
  if (!item) return res.status(404).json({ error: "Product not found" });
  res.json(item);
}));

productsRouter.post("/", handle(async (req, res) => {
  const input = createProductSchema.parse(req.body);
  res.status(201).json(await repo.createProduct(input));
}));

productsRouter.patch("/:id", handle(async (req, res) => {
  const input = updateProductSchema.parse(req.body);
  const item = await repo.updateProduct(req.params.id, input);
  if (!item) return res.status(404).json({ error: "Product not found" });
  res.json(item);
}));

productsRouter.delete("/:id", handle(async (req, res) => {
  const deleted = await repo.deleteProduct(req.params.id);
  if (!deleted) return res.status(404).json({ error: "Product not found" });
  res.status(204).end();
}));

// Validation errors become 400s; everything else is a 500 without internals.
productsRouter.use((err: unknown, _req: Request, res: Response, next: NextFunction) => {
  if (err instanceof ZodError) return res.status(400).json({ error: "Validation failed", issues: err.issues });
  next(err);
});

