package com.example.shop.orders;

import com.example.shop.web.PageResponse;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

import java.util.UUID;

@Service
@Transactional
public class OrderService {

    private final OrderRepository repository;

    public OrderService(OrderRepository repository) {
        this.repository = repository;
    }

    @Transactional(readOnly = true)
    public PageResponse<OrderResponse> list(int page, int size) {
        Page<Order> result = repository.findAll(PageRequest.of(page - 1, size, Sort.by(Sort.Direction.DESC, "createdAt")));
        return new PageResponse<>(result.map(OrderResponse::from).getContent(), page, size, result.getTotalElements(), result.getTotalPages());
    }

    @Transactional(readOnly = true)
    public OrderResponse get(UUID id) {
        return OrderResponse.from(find(id));
    }

    public OrderResponse create(CreateOrderRequest request) {
        Order order = new Order();
        order.setCustomerEmail(request.customerEmail());
        order.setReference(request.reference());
        order.setTotal(request.total());
        order.setStatus(request.status());
        order.setNotes(request.notes());
        return OrderResponse.from(repository.saveAndFlush(order));
    }

    public OrderResponse update(UUID id, UpdateOrderRequest request) {
        Order order = find(id);
        if (request.customerEmail() != null) order.setCustomerEmail(request.customerEmail());
        if (request.reference() != null) order.setReference(request.reference());
        if (request.total() != null) order.setTotal(request.total());
        if (request.status() != null) order.setStatus(request.status());
        if (request.notes() != null) order.setNotes(request.notes());
        return OrderResponse.from(repository.saveAndFlush(order));
    }

    public void delete(UUID id) {
        repository.delete(find(id));
    }

    private Order find(UUID id) {
        return repository.findById(id).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Order not found"));
    }
}

