using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using Shop.Api.Data;
using Shop.Api.Dtos;
using Shop.Api.Models;

namespace Shop.Api.Controllers;

[ApiController]
[Route("api/customers")]
public class CustomersController(AppDbContext db) : ControllerBase
{
    [HttpGet]
    public async Task<ActionResult<PagedResponse<CustomerResponse>>> List([FromQuery] int page = 1, [FromQuery] int pageSize = 20, CancellationToken ct = default)
    {
        page = Math.Max(page, 1);
        pageSize = Math.Clamp(pageSize, 1, 100);
        var query = db.Customers.AsNoTracking().OrderByDescending(x => x.CreatedAt);
        var total = await query.CountAsync(ct);
        var items = await query.Skip((page - 1) * pageSize).Take(pageSize).ToListAsync(ct);
        return new PagedResponse<CustomerResponse>(items.Select(CustomerResponse.From).ToList(), page, pageSize, total, (int)Math.Ceiling(total / (double)pageSize));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<CustomerResponse>> Get(Guid id, CancellationToken ct)
    {
        var entity = await db.Customers.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);
        return entity is null ? NotFound() : CustomerResponse.From(entity);
    }

    [HttpPost]
    public async Task<ActionResult<CustomerResponse>> Create(CreateCustomerRequest request, CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        var entity = new Customer
        {
            Id = Guid.NewGuid(),
            Name = request.Name!,
            Email = request.Email!,
            BirthDate = request.BirthDate,
            Active = request.Active.GetValueOrDefault(),
            CreatedAt = now,
            UpdatedAt = now
        };
        db.Customers.Add(entity);
        if (!await TrySaveAsync(ct)) return Conflict(Problem409());
        return CreatedAtAction(nameof(Get), new { id = entity.Id }, CustomerResponse.From(entity));
    }

    [HttpPatch("{id:guid}")]
    public async Task<ActionResult<CustomerResponse>> Update(Guid id, UpdateCustomerRequest request, CancellationToken ct)
    {
        var entity = await db.Customers.FirstOrDefaultAsync(x => x.Id == id, ct);
        if (entity is null) return NotFound();
        if (request.Name is not null) entity.Name = request.Name;
        if (request.Email is not null) entity.Email = request.Email;
        if (request.BirthDate is not null) entity.BirthDate = request.BirthDate.Value;
        if (request.Active is not null) entity.Active = request.Active.Value;
        entity.UpdatedAt = DateTime.UtcNow;
        if (!await TrySaveAsync(ct)) return Conflict(Problem409());
        return CustomerResponse.From(entity);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var deleted = await db.Customers.Where(x => x.Id == id).ExecuteDeleteAsync(ct);
        return deleted == 0 ? NotFound() : NoContent();
    }

    private async Task<bool> TrySaveAsync(CancellationToken ct)
    {
        try
        {
            await db.SaveChangesAsync(ct);
            return true;
        }
        catch (DbUpdateException)
        {
            // A unique index was violated (or another constraint): report a conflict, not a 500.
            return false;
        }
    }

    private static ProblemDetails Problem409() => new() { Status = StatusCodes.Status409Conflict, Title = "A customer with the same unique value already exists." };
}

