import math
import uuid
from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy import func, select
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session

from app.database import get_db
from app.articles.models import Article
from app.articles.schemas import ArticleCreate, ArticlePage, ArticleRead, ArticleUpdate

router = APIRouter(prefix="/articles", tags=["articles"])
DbSession = Annotated[Session, Depends(get_db)]


def _get_or_404(db: Session, item_id: uuid.UUID) -> Article:
    item = db.get(Article, item_id)
    if item is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Article not found")
    return item


def _commit(db: Session) -> None:
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail="A article with the same unique value already exists.")


@router.get("", response_model=ArticlePage)
def list_articles(db: DbSession, page: int = Query(1, ge=1), limit: int = Query(20, ge=1, le=100)) -> ArticlePage:
    total = db.scalar(select(func.count()).select_from(Article)) or 0
    items = db.scalars(select(Article).order_by(Article.created_at.desc()).offset((page - 1) * limit).limit(limit)).all()
    return ArticlePage(items=[ArticleRead.model_validate(item) for item in items], page=page, limit=limit, total=total, pages=math.ceil(total / limit))


@router.get("/{item_id}", response_model=ArticleRead)
def get_article(item_id: uuid.UUID, db: DbSession) -> Article:
    return _get_or_404(db, item_id)


@router.post("", response_model=ArticleRead, status_code=status.HTTP_201_CREATED)
def create_article(payload: ArticleCreate, db: DbSession) -> Article:
    item = Article(**payload.model_dump())
    db.add(item)
    _commit(db)
    db.refresh(item)
    return item


@router.patch("/{item_id}", response_model=ArticleRead)
def update_article(item_id: uuid.UUID, payload: ArticleUpdate, db: DbSession) -> Article:
    item = _get_or_404(db, item_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(item, key, value)
    _commit(db)
    db.refresh(item)
    return item


@router.delete("/{item_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_article(item_id: uuid.UUID, db: DbSession) -> None:
    db.delete(_get_or_404(db, item_id))
    _commit(db)

