import (
	"bytes"
	"fmt"
	"io"
	"log"
	"mime/multipart"
	"net/http"
	"os"
	"path/filepath"
)

func main() {
	var buf bytes.Buffer
	w := multipart.NewWriter(&buf)
	if file, err := os.Open("./a.png"); err == nil {
		part, _ := w.CreateFormFile("file", filepath.Base("./a.png"))
		io.Copy(part, file)
		file.Close()
	} else {
		log.Fatal(err)
	}
	w.WriteField("name", "x")
	w.Close()
	req, err := http.NewRequest("POST", "https://a.io/up", &buf)
	if err != nil {
		log.Fatal(err)
	}
	req.Header.Set("Content-Type", w.FormDataContentType())
	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		log.Fatal(err)
	}
	defer resp.Body.Close()
	data, err := io.ReadAll(resp.Body)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(resp.Status)
	fmt.Println(string(data))
}

