func main() {
	var buf bytes.Buffer
	w := multipart.NewWriter(&buf)
	w.WriteField("n", "@literal")
	if file, err := os.Open("/tmp/a b.pdf"); err == nil {
		part, _ := w.CreateFormFile("doc", filepath.Base("/tmp/a b.pdf"))
		io.Copy(part, file)
		file.Close()
	} else {
		log.Fatal(err)
	}
	w.WriteField("meta", "x")
	w.Close()
	req, err := http.NewRequest("POST", "https://a.io", &buf)
	if err != nil {
		log.Fatal(err)
	}
	req.Header.Set("Content-Type", w.FormDataContentType())
	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		log.Fatal(err)
	}
	defer resp.Body.Close()
	data, err := io.ReadAll(resp.Body)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(resp.Status)
	fmt.Println(string(data))
}

