export const BASE_URL = "https://petstore.example.com/v2";

export class ApiError extends Error {
  constructor(public status: number, public body: unknown) {
    super(`HTTP ${status}`);
  }
}

async function request<T>(method: string, path: string, query?: Record<string, unknown>, body?: unknown, init?: RequestInit): Promise<T> {
  const url = new URL(BASE_URL + path, typeof window === "undefined" ? "http://localhost" : window.location.origin);
  for (const [key, value] of Object.entries(query ?? {})) {
    if (value === undefined || value === null) continue;
    for (const v of Array.isArray(value) ? value : [value]) url.searchParams.append(key, String(v));
  }
  const response = await fetch(url, {
    ...init,
    method,
    headers: { Accept: "application/json", ...(body !== undefined ? { "Content-Type": "application/json" } : {}), ...init?.headers },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  const text = await response.text();
  const data = text ? (response.headers.get("content-type")?.includes("json") ? JSON.parse(text) : text) : undefined;
  if (!response.ok) throw new ApiError(response.status, data);
  return data as T;
}

