import { z } from "zod";

export const createBlogPostSchema = z.object({
  title: z.string().trim().min(1).max(255),
  slug: z.string().trim().min(1).max(255),
  body: z.string().max(10000).optional(),
  views: z.number().int().optional(),
  price: z.number(),
  active: z.boolean(),
  publishedAt: z.coerce.date().optional(),
  contact: z.string().email().optional(),
  site: z.string().url().optional(),
  ref: z.string().uuid(),
  status: z.enum(["draft", "live", "a.b"]),
  tags: z.array(z.string()).optional(),
  scores: z.array(z.number()),
  meta: z.record(z.string(), z.unknown()).optional(),
});

export const updateBlogPostSchema = createBlogPostSchema.partial();

export const listBlogPostQuerySchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

export type CreateBlogPostInput = z.infer<typeof createBlogPostSchema>;
export type UpdateBlogPostInput = z.infer<typeof updateBlogPostSchema>;

export interface BlogPost {
  id: string;
  title: string;
  slug: string;
  body?: string;
  views?: number;
  price: number;
  active: boolean;
  publishedAt?: Date;
  contact?: string;
  site?: string;
  ref: string;
  status: "draft" | "live" | "a.b";
  tags?: string[];
  scores: number[];
  meta?: Record<string, unknown>;
  createdAt: Date;
  updatedAt: Date;
}

import { PrismaClient } from "@prisma/client";

// One client per process; reuse it across hot reloads in development.
const globalForPrisma = globalThis as unknown as { prisma?: PrismaClient };
export const prisma = globalForPrisma.prisma ?? new PrismaClient();
if (process.env.NODE_ENV !== "production") globalForPrisma.prisma = prisma;

import { Prisma } from "@prisma/client";
import { prisma } from "../prisma";
import { CreateBlogPostInput, UpdateBlogPostInput } from "./blog-post.schema";

export function listBlogPosts(skip: number, take: number) {
  return prisma.blogPost.findMany({ skip, take, orderBy: { createdAt: "desc" } });
}

export function countBlogPosts() {
  return prisma.blogPost.count();
}

export function getBlogPost(id: string) {
  return prisma.blogPost.findUnique({ where: { id } });
}

export function createBlogPost(input: CreateBlogPostInput) {
  return prisma.blogPost.create({ data: input as Prisma.BlogPostCreateInput });
}

export async function updateBlogPost(id: string, input: UpdateBlogPostInput) {
  try {
    return await prisma.blogPost.update({ where: { id }, data: input as Prisma.BlogPostUpdateInput });
  } catch (error) {
    // P2025: record to update not found
    if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === "P2025") return null;
    throw error;
  }
}

export async function deleteBlogPost(id: string) {
  const { count } = await prisma.blogPost.deleteMany({ where: { id } });
  return count > 0;
}

import { NextFunction, Request, Response, Router } from "express";
import { ZodError } from "zod";
import { createBlogPostSchema, listBlogPostQuerySchema, updateBlogPostSchema } from "./blog-post.schema";
import * as repo from "./blog-post.repository";

export const blogPostsRouter = Router();

// Express 4 does not catch rejected promises; this forwards them to the error handler.
const handle = (fn: (req: Request, res: Response) => Promise<unknown>) =>
  (req: Request, res: Response, next: NextFunction) => fn(req, res).catch(next);

blogPostsRouter.get("/", handle(async (req, res) => {
  const { page, limit } = listBlogPostQuerySchema.parse(req.query);
  const [items, total] = await Promise.all([repo.listBlogPosts((page - 1) * limit, limit), repo.countBlogPosts()]);
  res.json({ items, page, limit, total, pages: Math.ceil(total / limit) });
}));

blogPostsRouter.get("/:id", handle(async (req, res) => {
  const item = await repo.getBlogPost(req.params.id);
  if (!item) return res.status(404).json({ error: "BlogPost not found" });
  res.json(item);
}));

blogPostsRouter.post("/", handle(async (req, res) => {
  const input = createBlogPostSchema.parse(req.body);
  res.status(201).json(await repo.createBlogPost(input));
}));

blogPostsRouter.patch("/:id", handle(async (req, res) => {
  const input = updateBlogPostSchema.parse(req.body);
  const item = await repo.updateBlogPost(req.params.id, input);
  if (!item) return res.status(404).json({ error: "BlogPost not found" });
  res.json(item);
}));

blogPostsRouter.delete("/:id", handle(async (req, res) => {
  const deleted = await repo.deleteBlogPost(req.params.id);
  if (!deleted) return res.status(404).json({ error: "BlogPost not found" });
  res.status(204).end();
}));

// Validation errors become 400s; everything else is a 500 without internals.
blogPostsRouter.use((err: unknown, _req: Request, res: Response, next: NextFunction) => {
  if (err instanceof ZodError) return res.status(400).json({ error: "Validation failed", issues: err.issues });
  next(err);
});

