import { InferSchemaType, Schema, model, models, Model } from "mongoose";

const blogPostSchema = new Schema(
  {
    title: { type: String, required: true, trim: true },
    slug: { type: String, required: true, unique: true, trim: true },
    body: { type: String, trim: true },
    views: { type: Number },
    price: { type: Number, required: true },
    active: { type: Boolean, required: true },
    publishedAt: { type: Date },
    contact: { type: String, unique: true, lowercase: true, trim: true },
    site: { type: String },
    ref: { type: String, required: true },
    status: { type: String, required: true, enum: ["draft","live","a.b"] },
    tags: { type: [String] },
    scores: { type: [Number], required: true },
    meta: { type: Schema.Types.Mixed },
  },
  {
    timestamps: true,
    // Expose "id" instead of "_id" and drop "__v" in JSON responses.
    toJSON: { virtuals: true, versionKey: false, transform: (_doc, ret: Record<string, unknown>) => { delete ret._id; return ret; } },
  },
);

export type BlogPostDocument = InferSchemaType<typeof blogPostSchema>;
// models.BlogPost avoids OverwriteModelError on hot reload (Next.js, nodemon).
export const BlogPostModel = (models.BlogPost as Model<BlogPostDocument>) ?? model("BlogPost", blogPostSchema);

import { isValidObjectId } from "mongoose";
import { BlogPostModel } from "./blog-post.model";
import { CreateBlogPostInput, UpdateBlogPostInput } from "./blog-post.schema";

export function listBlogPosts(skip: number, take: number) {
  return BlogPostModel.find().sort({ createdAt: -1 }).skip(skip).limit(take);
}

export function countBlogPosts() {
  return BlogPostModel.countDocuments();
}

export async function getBlogPost(id: string) {
  // An invalid ObjectId would throw a CastError; treat it as "not found".
  return isValidObjectId(id) ? BlogPostModel.findById(id) : null;
}

export function createBlogPost(input: CreateBlogPostInput) {
  return BlogPostModel.create(input);
}

export async function updateBlogPost(id: string, input: UpdateBlogPostInput) {
  return isValidObjectId(id) ? BlogPostModel.findByIdAndUpdate(id, input, { new: true, runValidators: true }) : null;
}

export async function deleteBlogPost(id: string) {
  if (!isValidObjectId(id)) return false;
  return (await BlogPostModel.findByIdAndDelete(id)) !== null;
}

