import { randomUUID } from "node:crypto";
import { CreateBlogPostInput, BlogPost, UpdateBlogPostInput } from "./blog-post.schema";

// In-memory store for prototypes and tests; swap for a database before production.
const store = new Map<string, BlogPost>();

export async function listBlogPosts(skip: number, take: number): Promise<BlogPost[]> {
  return [...store.values()].sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime()).slice(skip, skip + take);
}

export async function countBlogPosts(): Promise<number> {
  return store.size;
}

export async function getBlogPost(id: string): Promise<BlogPost | undefined> {
  return store.get(id);
}

export async function createBlogPost(input: CreateBlogPostInput): Promise<BlogPost> {
  const now = new Date();
  const item: BlogPost = { id: randomUUID(), ...input, createdAt: now, updatedAt: now };
  store.set(item.id, item);
  return item;
}

export async function updateBlogPost(id: string, input: UpdateBlogPostInput): Promise<BlogPost | undefined> {
  const existing = store.get(id);
  if (!existing) return undefined;
  const item: BlogPost = { ...existing, ...input, updatedAt: new Date() };
  store.set(id, item);
  return item;
}

export async function deleteBlogPost(id: string): Promise<boolean> {
  return store.delete(id);
}

