import { Injectable, NotFoundException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import { PrismaService } from "../prisma/prisma.service";
import { CreateBlogPostDto } from "./dto/create-blog-post.dto";
import { UpdateBlogPostDto } from "./dto/update-blog-post.dto";

@Injectable()
export class BlogPostsService {
  constructor(private readonly prisma: PrismaService) {}

  async findAll(page: number, limit: number) {
    const [items, total] = await this.prisma.$transaction([
      this.prisma.blogPost.findMany({ skip: (page - 1) * limit, take: limit, orderBy: { createdAt: "desc" } }),
      this.prisma.blogPost.count(),
    ]);
    return { items, page, limit, total, pages: Math.ceil(total / limit) };
  }

  async findOne(id: string) {
    const item = await this.prisma.blogPost.findUnique({ where: { id } });
    if (!item) throw new NotFoundException("BlogPost not found");
    return item;
  }

  create(dto: CreateBlogPostDto) {
    return this.prisma.blogPost.create({ data: dto as Prisma.BlogPostCreateInput });
  }

  async update(id: string, dto: UpdateBlogPostDto) {
    await this.findOne(id);
    return this.prisma.blogPost.update({ where: { id }, data: dto as Prisma.BlogPostUpdateInput });
  }

  async remove(id: string) {
    await this.findOne(id);
    await this.prisma.blogPost.delete({ where: { id } });
  }
}

