    const [items, total] = await Promise.all([
      this.model.find().sort({ createdAt: -1 }).skip((page - 1) * limit).limit(limit).exec(),
      this.model.countDocuments().exec(),
    ]);
    return { items, page, limit, total, pages: Math.ceil(total / limit) };
