export type BlogPost = CreateBlogPostDto & { id: string; createdAt: Date; updatedAt: Date };

// In-memory store for prototypes and tests; swap for a database before production.
@Injectable()
export class BlogPostsService {
  private readonly store = new Map<string, BlogPost>();

  findAll(page: number, limit: number) {
    const all = [...this.store.values()].sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
    return { items: all.slice((page - 1) * limit, page * limit), page, limit, total: all.length, pages: Math.ceil(all.length / limit) };
  }

  findOne(id: string) {
    const item = this.store.get(id);
    if (!item) throw new NotFoundException("BlogPost not found");
    return item;
  }

  create(dto: CreateBlogPostDto) {
    const now = new Date();
    const item: BlogPost = { ...dto, id: randomUUID(), createdAt: now, updatedAt: now };
    this.store.set(item.id, item);
    return item;
  }

  update(id: string, dto: UpdateBlogPostDto) {
    const item = { ...this.findOne(id), ...dto, updatedAt: new Date() };
    this.store.set(id, item);
    return item;
  }

  remove(id: string) {
    this.findOne(id);
    this.store.delete(id);
  }
}

