import { FastifyInstance } from "fastify";
import { CreateBlogPostInput, UpdateBlogPostInput } from "./blog-post.schema";
import * as repo from "./blog-post.repository";

// Fastify validates bodies with JSON Schema (Ajv) before the handler runs.
const properties = {
    title: {"type":"string","minLength":1,"maxLength":255},
    slug: {"type":"string","minLength":1,"maxLength":255},
    body: {"type":"string"},
    views: {"type":"integer"},
    price: {"type":"number"},
    active: {"type":"boolean"},
    publishedAt: {"type":"string","format":"date-time"},
    contact: {"type":"string","format":"email"},
    site: {"type":"string","format":"uri"},
    ref: {"type":"string","format":"uuid"},
    status: {"type":"string","enum":["draft","live","a.b"]},
    tags: {"type":"array","items":{"type":"string"}},
    scores: {"type":"array","items":{"type":"number"}},
    meta: {"type":"object"},
};
const createBody = { type: "object", properties, required: ["title","slug","price","active","ref","status","scores"], additionalProperties: false } as const;
const updateBody = { type: "object", properties, additionalProperties: false } as const;
const idParams = { type: "object", properties: { id: { type: "string" } }, required: ["id"] } as const;
const listQuery = { type: "object", properties: { page: { type: "integer", minimum: 1, default: 1 }, limit: { type: "integer", minimum: 1, maximum: 100, default: 20 } } } as const;

export async function blogPostsRoutes(app: FastifyInstance) {
  app.get<{ Querystring: { page: number; limit: number } }>("/", { schema: { querystring: listQuery } }, async req => {
    const { page, limit } = req.query;
    const [items, total] = await Promise.all([repo.listBlogPosts((page - 1) * limit, limit), repo.countBlogPosts()]);
    return { items, page, limit, total, pages: Math.ceil(total / limit) };
  });

  app.get<{ Params: { id: string } }>("/:id", { schema: { params: idParams } }, async (req, reply) => {
    const item = await repo.getBlogPost(req.params.id);
    return item ?? reply.code(404).send({ error: "BlogPost not found" });
  });

  app.post<{ Body: CreateBlogPostInput }>("/", { schema: { body: createBody } }, async (req, reply) => {
    return reply.code(201).send(await repo.createBlogPost(req.body));
  });

  app.patch<{ Params: { id: string }; Body: UpdateBlogPostInput }>("/:id", { schema: { params: idParams, body: updateBody } }, async (req, reply) => {
    const item = await repo.updateBlogPost(req.params.id, req.body);
    return item ?? reply.code(404).send({ error: "BlogPost not found" });
  });

  app.delete<{ Params: { id: string } }>("/:id", { schema: { params: idParams } }, async (req, reply) => {
    const deleted = await repo.deleteBlogPost(req.params.id);
    return deleted ? reply.code(204).send() : reply.code(404).send({ error: "BlogPost not found" });
  });
}

