import { z } from "zod";

export const createBlogPostSchema = z.object({
  title: z.string().trim().min(1).max(255),
  slug: z.string().trim().min(1).max(255),
  body: z.string().max(10000).optional(),
  views: z.number().int().optional(),
  price: z.number(),
  active: z.boolean(),
  publishedAt: z.coerce.date().optional(),
  contact: z.string().email().optional(),
  site: z.string().url().optional(),
  ref: z.string().uuid(),
  status: z.enum(["draft", "live", "a.b"]),
  tags: z.array(z.string()).optional(),
  scores: z.array(z.number()),
  meta: z.record(z.string(), z.unknown()).optional(),
});

export const updateBlogPostSchema = createBlogPostSchema.partial();

export const listBlogPostQuerySchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

export type CreateBlogPostInput = z.infer<typeof createBlogPostSchema>;
export type UpdateBlogPostInput = z.infer<typeof updateBlogPostSchema>;

export interface BlogPost {
  id: string;
  title: string;
  slug: string;
  body?: string;
  views?: number;
  price: number;
  active: boolean;
  publishedAt?: Date;
  contact?: string;
  site?: string;
  ref: string;
  status: "draft" | "live" | "a.b";
  tags?: string[];
  scores: number[];
  meta?: Record<string, unknown>;
  createdAt: Date;
  updatedAt: Date;
}

import { randomUUID } from "node:crypto";
import { CreateBlogPostInput, BlogPost, UpdateBlogPostInput } from "./blog-post.schema";

// In-memory store for prototypes and tests; swap for a database before production.
const store = new Map<string, BlogPost>();

export async function listBlogPosts(skip: number, take: number): Promise<BlogPost[]> {
  return [...store.values()].sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime()).slice(skip, skip + take);
}

export async function countBlogPosts(): Promise<number> {
  return store.size;
}

export async function getBlogPost(id: string): Promise<BlogPost | undefined> {
  return store.get(id);
}

export async function createBlogPost(input: CreateBlogPostInput): Promise<BlogPost> {
  const now = new Date();
  const item: BlogPost = { id: randomUUID(), ...input, createdAt: now, updatedAt: now };
  store.set(item.id, item);
  return item;
}

export async function updateBlogPost(id: string, input: UpdateBlogPostInput): Promise<BlogPost | undefined> {
  const existing = store.get(id);
  if (!existing) return undefined;
  const item: BlogPost = { ...existing, ...input, updatedAt: new Date() };
  store.set(id, item);
  return item;
}

export async function deleteBlogPost(id: string): Promise<boolean> {
  return store.delete(id);
}

