package com.example.demo.blogentries;

import com.example.demo.web.PageResponse;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

import java.util.ArrayList;
import java.util.UUID;

@Service
@Transactional
public class BlogEntryService {

    private final BlogEntryRepository repository;

    public BlogEntryService(BlogEntryRepository repository) {
        this.repository = repository;
    }

    @Transactional(readOnly = true)
    public PageResponse<BlogEntryResponse> list(int page, int size) {
        Page<BlogEntry> result = repository.findAll(PageRequest.of(page - 1, size, Sort.by(Sort.Direction.DESC, "createdAt")));
        return new PageResponse<>(result.map(BlogEntryResponse::from).getContent(), page, size, result.getTotalElements(), result.getTotalPages());
    }

    @Transactional(readOnly = true)
    public BlogEntryResponse get(UUID id) {
        return BlogEntryResponse.from(find(id));
    }

    public BlogEntryResponse create(CreateBlogEntryRequest request) {
        BlogEntry blogEntry = new BlogEntry();
        blogEntry.setTitle(request.title());
        blogEntry.setSlug(request.slug());
        blogEntry.setBody(request.body());
        blogEntry.setViews(request.views());
        blogEntry.setPrice(request.price());
        blogEntry.setActive(request.active());
        blogEntry.setPublishedAt(request.publishedAt());
        blogEntry.setContact(request.contact());
        blogEntry.setSite(request.site());
        blogEntry.setRef(request.ref());
        blogEntry.setStatus(request.status());
        blogEntry.setTags(request.tags() == null ? new ArrayList<>() : new ArrayList<>(request.tags()));
        blogEntry.setScores(request.scores() == null ? new ArrayList<>() : new ArrayList<>(request.scores()));
        blogEntry.setMeta(request.meta());
        return BlogEntryResponse.from(repository.saveAndFlush(blogEntry));
    }

    public BlogEntryResponse update(UUID id, UpdateBlogEntryRequest request) {
        BlogEntry blogEntry = find(id);
        if (request.title() != null) blogEntry.setTitle(request.title());
        if (request.slug() != null) blogEntry.setSlug(request.slug());
        if (request.body() != null) blogEntry.setBody(request.body());
        if (request.views() != null) blogEntry.setViews(request.views());
        if (request.price() != null) blogEntry.setPrice(request.price());
        if (request.active() != null) blogEntry.setActive(request.active());
        if (request.publishedAt() != null) blogEntry.setPublishedAt(request.publishedAt());
        if (request.contact() != null) blogEntry.setContact(request.contact());
        if (request.site() != null) blogEntry.setSite(request.site());
        if (request.ref() != null) blogEntry.setRef(request.ref());
        if (request.status() != null) blogEntry.setStatus(request.status());
        if (request.tags() != null) blogEntry.setTags(new ArrayList<>(request.tags()));
        if (request.scores() != null) blogEntry.setScores(new ArrayList<>(request.scores()));
        if (request.meta() != null) blogEntry.setMeta(request.meta());
        return BlogEntryResponse.from(repository.saveAndFlush(blogEntry));
    }

    public void delete(UUID id) {
        repository.delete(find(id));
    }

    private BlogEntry find(UUID id) {
        return repository.findById(id).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "BlogEntry not found"));
    }
}

