using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using MyApi.Data;
using MyApi.Dtos;
using MyApi.Models;

namespace MyApi.Controllers;

[ApiController]
[Route("api/blog-entries")]
public class BlogEntriesController(AppDbContext db) : ControllerBase
{
    [HttpGet]
    public async Task<ActionResult<PagedResponse<BlogEntryResponse>>> List([FromQuery] int page = 1, [FromQuery] int pageSize = 20, CancellationToken ct = default)
    {
        page = Math.Max(page, 1);
        pageSize = Math.Clamp(pageSize, 1, 100);
        var query = db.BlogEntries.AsNoTracking().OrderByDescending(x => x.CreatedAt);
        var total = await query.CountAsync(ct);
        var items = await query.Skip((page - 1) * pageSize).Take(pageSize).ToListAsync(ct);
        return new PagedResponse<BlogEntryResponse>(items.Select(BlogEntryResponse.From).ToList(), page, pageSize, total, (int)Math.Ceiling(total / (double)pageSize));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<BlogEntryResponse>> Get(Guid id, CancellationToken ct)
    {
        var entity = await db.BlogEntries.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);
        return entity is null ? NotFound() : BlogEntryResponse.From(entity);
    }

    [HttpPost]
    public async Task<ActionResult<BlogEntryResponse>> Create(CreateBlogEntryRequest request, CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        var entity = new BlogEntry
        {
            Id = Guid.NewGuid(),
            Title = request.Title!,
            Slug = request.Slug!,
            Body = request.Body,
            Views = request.Views,
            Price = request.Price.GetValueOrDefault(),
            Active = request.Active.GetValueOrDefault(),
            PublishedAt = request.PublishedAt,
            Contact = request.Contact,
            Site = request.Site,
            Ref = request.Ref.GetValueOrDefault(),
            Status = request.Status!,
            Tags = request.Tags ?? [],
            Scores = request.Scores ?? [],
            Meta = request.Meta,
            CreatedAt = now,
            UpdatedAt = now
        };
        db.BlogEntries.Add(entity);
        if (!await TrySaveAsync(ct)) return Conflict(Problem409());
        return CreatedAtAction(nameof(Get), new { id = entity.Id }, BlogEntryResponse.From(entity));
    }

    [HttpPatch("{id:guid}")]
    public async Task<ActionResult<BlogEntryResponse>> Update(Guid id, UpdateBlogEntryRequest request, CancellationToken ct)
    {
        var entity = await db.BlogEntries.FirstOrDefaultAsync(x => x.Id == id, ct);
        if (entity is null) return NotFound();
        if (request.Title is not null) entity.Title = request.Title;
        if (request.Slug is not null) entity.Slug = request.Slug;
        if (request.Body is not null) entity.Body = request.Body;
        if (request.Views is not null) entity.Views = request.Views.Value;
        if (request.Price is not null) entity.Price = request.Price.Value;
        if (request.Active is not null) entity.Active = request.Active.Value;
        if (request.PublishedAt is not null) entity.PublishedAt = request.PublishedAt.Value;
        if (request.Contact is not null) entity.Contact = request.Contact;
        if (request.Site is not null) entity.Site = request.Site;
        if (request.Ref is not null) entity.Ref = request.Ref.Value;
        if (request.Status is not null) entity.Status = request.Status;
        if (request.Tags is not null) entity.Tags = request.Tags;
        if (request.Scores is not null) entity.Scores = request.Scores;
        if (request.Meta is not null) entity.Meta = request.Meta;
        entity.UpdatedAt = DateTime.UtcNow;
        if (!await TrySaveAsync(ct)) return Conflict(Problem409());
        return BlogEntryResponse.From(entity);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var deleted = await db.BlogEntries.Where(x => x.Id == id).ExecuteDeleteAsync(ct);
        return deleted == 0 ? NotFound() : NoContent();
    }

    private async Task<bool> TrySaveAsync(CancellationToken ct)
    {
        try
        {
            await db.SaveChangesAsync(ct);
            return true;
        }
        catch (DbUpdateException)
        {
            // A unique index was violated (or another constraint): report a conflict, not a 500.
            return false;
        }
    }

    private static ProblemDetails Problem409() => new() { Status = StatusCodes.Status409Conflict, Title = "A blogentry with the same unique value already exists." };
}

