import math
import uuid
from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy import func, select
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session

from app.database import get_db
from app.blog_entries.models import BlogEntry
from app.blog_entries.schemas import BlogEntryCreate, BlogEntryPage, BlogEntryRead, BlogEntryUpdate

router = APIRouter(prefix="/blog-entries", tags=["blog_entries"])
DbSession = Annotated[Session, Depends(get_db)]


def _get_or_404(db: Session, item_id: uuid.UUID) -> BlogEntry:
    item = db.get(BlogEntry, item_id)
    if item is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="BlogEntry not found")
    return item


def _commit(db: Session) -> None:
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail="A blog entry with the same unique value already exists.")


@router.get("", response_model=BlogEntryPage)
def list_blog_entries(db: DbSession, page: int = Query(1, ge=1), limit: int = Query(20, ge=1, le=100)) -> BlogEntryPage:
    total = db.scalar(select(func.count()).select_from(BlogEntry)) or 0
    items = db.scalars(select(BlogEntry).order_by(BlogEntry.created_at.desc()).offset((page - 1) * limit).limit(limit)).all()
    return BlogEntryPage(items=[BlogEntryRead.model_validate(item) for item in items], page=page, limit=limit, total=total, pages=math.ceil(total / limit))


@router.get("/{item_id}", response_model=BlogEntryRead)
def get_blog_entry(item_id: uuid.UUID, db: DbSession) -> BlogEntry:
    return _get_or_404(db, item_id)


@router.post("", response_model=BlogEntryRead, status_code=status.HTTP_201_CREATED)
def create_blog_entry(payload: BlogEntryCreate, db: DbSession) -> BlogEntry:
    item = BlogEntry(**payload.model_dump())
    db.add(item)
    _commit(db)
    db.refresh(item)
    return item


@router.patch("/{item_id}", response_model=BlogEntryRead)
def update_blog_entry(item_id: uuid.UUID, payload: BlogEntryUpdate, db: DbSession) -> BlogEntry:
    item = _get_or_404(db, item_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(item, key, value)
    _commit(db)
    db.refresh(item)
    return item


