import { z } from "zod";

export const createCategorySchema = z.object({
  name: z.string().trim().min(1).max(255),
  parent: z.string().uuid().optional(),
  note: z.string().max(10000).optional(),
  kind: z.enum(["a", "b"]).optional(),
  count: z.number().int(),
  ratio: z.number().optional(),
  at: z.coerce.date().optional(),
  x: z.record(z.string(), z.unknown()).optional(),
  list: z.array(z.number()).optional(),
  t: z.array(z.string()).optional(),
  b: z.boolean().optional(),
  l: z.string().url().optional(),
  d: z.number().optional(),
  dbl: z.number().optional(),
  s2: z.coerce.date().optional(),
});

export const updateCategorySchema = createCategorySchema.partial();

export const listCategoryQuerySchema = z.object({
  page: z.coerce.number().int().min(1).default(1),
  limit: z.coerce.number().int().min(1).max(100).default(20),
});

export type CreateCategoryInput = z.infer<typeof createCategorySchema>;
export type UpdateCategoryInput = z.infer<typeof updateCategorySchema>;

export interface Category {
  id: string;
  name: string;
  parent?: string;
  note?: string;
  kind?: "a" | "b";
  count: number;
  ratio?: number;
  at?: Date;
  x?: Record<string, unknown>;
  list?: number[];
  t?: string[];
  b?: boolean;
  l?: string;
  d?: number;
  dbl?: number;
  s2?: Date;
  createdAt: Date;
  updatedAt: Date;
}

import { PrismaClient } from "@prisma/client";

// One client per process; reuse it across hot reloads in development.
const globalForPrisma = globalThis as unknown as { prisma?: PrismaClient };
export const prisma = globalForPrisma.prisma ?? new PrismaClient();
if (process.env.NODE_ENV !== "production") globalForPrisma.prisma = prisma;

import { Prisma } from "@prisma/client";
import { prisma } from "../prisma";
import { CreateCategoryInput, UpdateCategoryInput } from "./category.schema";

export function listCategories(skip: number, take: number) {
  return prisma.category.findMany({ skip, take, orderBy: { createdAt: "desc" } });
}

export function countCategories() {
  return prisma.category.count();
}

export function getCategory(id: string) {
  return prisma.category.findUnique({ where: { id } });
}

export function createCategory(input: CreateCategoryInput) {
  return prisma.category.create({ data: input as Prisma.CategoryCreateInput });
}

export async function updateCategory(id: string, input: UpdateCategoryInput) {
  try {
    return await prisma.category.update({ where: { id }, data: input as Prisma.CategoryUpdateInput });
  } catch (error) {
    // P2025: record to update not found
    if (error instanceof Prisma.PrismaClientKnownRequestError && error.code === "P2025") return null;
    throw error;
  }
}

export async function deleteCategory(id: string) {
  const { count } = await prisma.category.deleteMany({ where: { id } });
  return count > 0;
}

import { NextFunction, Request, Response, Router } from "express";
import { ZodError } from "zod";
import { createCategorySchema, listCategoryQuerySchema, updateCategorySchema } from "./category.schema";
import * as repo from "./category.repository";

export const categoriesRouter = Router();

// Express 4 does not catch rejected promises; this forwards them to the error handler.
const handle = (fn: (req: Request, res: Response) => Promise<unknown>) =>
  (req: Request, res: Response, next: NextFunction) => fn(req, res).catch(next);

categoriesRouter.get("/", handle(async (req, res) => {
  const { page, limit } = listCategoryQuerySchema.parse(req.query);
  const [items, total] = await Promise.all([repo.listCategories((page - 1) * limit, limit), repo.countCategories()]);
  res.json({ items, page, limit, total, pages: Math.ceil(total / limit) });
}));

categoriesRouter.get("/:id", handle(async (req, res) => {
  const item = await repo.getCategory(req.params.id);
  if (!item) return res.status(404).json({ error: "Category not found" });
  res.json(item);
}));

categoriesRouter.post("/", handle(async (req, res) => {
  const input = createCategorySchema.parse(req.body);
  res.status(201).json(await repo.createCategory(input));
}));

categoriesRouter.patch("/:id", handle(async (req, res) => {
  const input = updateCategorySchema.parse(req.body);
  const item = await repo.updateCategory(req.params.id, input);
  if (!item) return res.status(404).json({ error: "Category not found" });
  res.json(item);
}));

categoriesRouter.delete("/:id", handle(async (req, res) => {
  const deleted = await repo.deleteCategory(req.params.id);
  if (!deleted) return res.status(404).json({ error: "Category not found" });
  res.status(204).end();
}));

// Validation errors become 400s; everything else is a 500 without internals.
categoriesRouter.use((err: unknown, _req: Request, res: Response, next: NextFunction) => {
  if (err instanceof ZodError) return res.status(400).json({ error: "Validation failed", issues: err.issues });
  next(err);
});

