package com.example.demo.categories;

import com.example.demo.web.PageResponse;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

import java.util.ArrayList;
import java.util.UUID;

@Service
@Transactional
public class CategoryService {

    private final CategoryRepository repository;

    public CategoryService(CategoryRepository repository) {
        this.repository = repository;
    }

    @Transactional(readOnly = true)
    public PageResponse<CategoryResponse> list(int page, int size) {
        Page<Category> result = repository.findAll(PageRequest.of(page - 1, size, Sort.by(Sort.Direction.DESC, "createdAt")));
        return new PageResponse<>(result.map(CategoryResponse::from).getContent(), page, size, result.getTotalElements(), result.getTotalPages());
    }

    @Transactional(readOnly = true)
    public CategoryResponse get(UUID id) {
        return CategoryResponse.from(find(id));
    }

    public CategoryResponse create(CreateCategoryRequest request) {
        Category category = new Category();
        category.setName(request.name());
        category.setParent(request.parent());
        category.setNote(request.note());
        category.setKind(request.kind());
        category.setCount(request.count());
        category.setRatio(request.ratio());
        category.setAt(request.at());
        category.setX(request.x());
        category.setList(request.list() == null ? new ArrayList<>() : new ArrayList<>(request.list()));
        category.setT(request.t() == null ? new ArrayList<>() : new ArrayList<>(request.t()));
        category.setB(request.b());
        category.setL(request.l());
        category.setD(request.d());
        category.setDbl(request.dbl());
        category.setS2(request.s2());
        return CategoryResponse.from(repository.saveAndFlush(category));
    }

    public CategoryResponse update(UUID id, UpdateCategoryRequest request) {
        Category category = find(id);
        if (request.name() != null) category.setName(request.name());
        if (request.parent() != null) category.setParent(request.parent());
        if (request.note() != null) category.setNote(request.note());
        if (request.kind() != null) category.setKind(request.kind());
        if (request.count() != null) category.setCount(request.count());
        if (request.ratio() != null) category.setRatio(request.ratio());
        if (request.at() != null) category.setAt(request.at());
        if (request.x() != null) category.setX(request.x());
        if (request.list() != null) category.setList(new ArrayList<>(request.list()));
        if (request.t() != null) category.setT(new ArrayList<>(request.t()));
        if (request.b() != null) category.setB(request.b());
        if (request.l() != null) category.setL(request.l());
        if (request.d() != null) category.setD(request.d());
        if (request.dbl() != null) category.setDbl(request.dbl());
        if (request.s2() != null) category.setS2(request.s2());
        return CategoryResponse.from(repository.saveAndFlush(category));
    }

    public void delete(UUID id) {
        repository.delete(find(id));
    }

    private Category find(UUID id) {
        return repository.findById(id).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Category not found"));
    }
}

