namespace MyApi.Controllers;

[ApiController]
[Route("api/categories")]
public class CategoriesController(AppDbContext db) : ControllerBase
{
    [HttpGet]
    public async Task<ActionResult<PagedResponse<CategoryResponse>>> List([FromQuery] int page = 1, [FromQuery] int pageSize = 20, CancellationToken ct = default)
    {
        page = Math.Max(page, 1);
        pageSize = Math.Clamp(pageSize, 1, 100);
        var query = db.Categories.AsNoTracking().OrderByDescending(x => x.CreatedAt);
        var total = await query.CountAsync(ct);
        var items = await query.Skip((page - 1) * pageSize).Take(pageSize).ToListAsync(ct);
        return new PagedResponse<CategoryResponse>(items.Select(CategoryResponse.From).ToList(), page, pageSize, total, (int)Math.Ceiling(total / (double)pageSize));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<CategoryResponse>> Get(Guid id, CancellationToken ct)
    {
        var entity = await db.Categories.AsNoTracking().FirstOrDefaultAsync(x => x.Id == id, ct);
        return entity is null ? NotFound() : CategoryResponse.From(entity);
    }

    [HttpPost]
    public async Task<ActionResult<CategoryResponse>> Create(CreateCategoryRequest request, CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        var entity = new Category
        {
            Id = Guid.NewGuid(),
            Name = request.Name!,
            Parent = request.Parent,
            Note = request.Note,
            Kind = request.Kind,
            Count = request.Count.GetValueOrDefault(),
            Ratio = request.Ratio,
            At = request.At,
            X = request.X,
            List = request.List ?? [],
            T = request.T ?? [],
            B = request.B,
            L = request.L,
            D = request.D,
            Dbl = request.Dbl,
            S2 = request.S2,
            CreatedAt = now,
            UpdatedAt = now
        };
        db.Categories.Add(entity);
        if (!await TrySaveAsync(ct)) return Conflict(Problem409());
        return CreatedAtAction(nameof(Get), new { id = entity.Id }, CategoryResponse.From(entity));
    }

    [HttpPatch("{id:guid}")]
    public async Task<ActionResult<CategoryResponse>> Update(Guid id, UpdateCategoryRequest request, CancellationToken ct)
    {
        var entity = await db.Categories.FirstOrDefaultAsync(x => x.Id == id, ct);
        if (entity is null) return NotFound();
        if (request.Name is not null) entity.Name = request.Name;
        if (request.Parent is not null) entity.Parent = request.Parent.Value;
        if (request.Note is not null) entity.Note = request.Note;
        if (request.Kind is not null) entity.Kind = request.Kind;
        if (request.Count is not null) entity.Count = request.Count.Value;
        if (request.Ratio is not null) entity.Ratio = request.Ratio.Value;
        if (request.At is not null) entity.At = request.At.Value;
        if (request.X is not null) entity.X = request.X;
        if (request.List is not null) entity.List = request.List;
        if (request.T is not null) entity.T = request.T;
        if (request.B is not null) entity.B = request.B.Value;
        if (request.L is not null) entity.L = request.L;
        if (request.D is not null) entity.D = request.D.Value;
        if (request.Dbl is not null) entity.Dbl = request.Dbl.Value;
        if (request.S2 is not null) entity.S2 = request.S2.Value;
        entity.UpdatedAt = DateTime.UtcNow;
        if (!await TrySaveAsync(ct)) return Conflict(Problem409());
        return CategoryResponse.From(entity);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var deleted = await db.Categories.Where(x => x.Id == id).ExecuteDeleteAsync(ct);
        return deleted == 0 ? NotFound() : NoContent();
    }

    private async Task<bool> TrySaveAsync(CancellationToken ct)
    {
        try
        {
            await db.SaveChangesAsync(ct);
            return true;
        }
        catch (DbUpdateException)
        {
            // A unique index was violated (or another constraint): report a conflict, not a 500.
            return false;
        }
    }

    private static ProblemDetails Problem409() => new() { Status = StatusCodes.Status409Conflict, Title = "A category with the same unique value already exists." };
}

