import math
import uuid
from typing import Annotated

from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy import func, select
from sqlalchemy.exc import IntegrityError
from sqlalchemy.orm import Session

from app.database import get_db
from app.categories.models import Category
from app.categories.schemas import CategoryCreate, CategoryPage, CategoryRead, CategoryUpdate

router = APIRouter(prefix="/categories", tags=["categories"])
DbSession = Annotated[Session, Depends(get_db)]


def _get_or_404(db: Session, item_id: uuid.UUID) -> Category:
    item = db.get(Category, item_id)
    if item is None:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Category not found")
    return item


def _commit(db: Session) -> None:
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
        raise HTTPException(status_code=status.HTTP_409_CONFLICT, detail="A category with the same unique value already exists.")


@router.get("", response_model=CategoryPage)
def list_categories(db: DbSession, page: int = Query(1, ge=1), limit: int = Query(20, ge=1, le=100)) -> CategoryPage:
    total = db.scalar(select(func.count()).select_from(Category)) or 0
    items = db.scalars(select(Category).order_by(Category.created_at.desc()).offset((page - 1) * limit).limit(limit)).all()
    return CategoryPage(items=[CategoryRead.model_validate(item) for item in items], page=page, limit=limit, total=total, pages=math.ceil(total / limit))


@router.get("/{item_id}", response_model=CategoryRead)
def get_category(item_id: uuid.UUID, db: DbSession) -> Category:
    return _get_or_404(db, item_id)


@router.post("", response_model=CategoryRead, status_code=status.HTTP_201_CREATED)
def create_category(payload: CategoryCreate, db: DbSession) -> Category:
    item = Category(**payload.model_dump())
    db.add(item)
    _commit(db)
    db.refresh(item)
    return item


@router.patch("/{item_id}", response_model=CategoryRead)
def update_category(item_id: uuid.UUID, payload: CategoryUpdate, db: DbSession) -> Category:
    item = _get_or_404(db, item_id)
    for key, value in payload.model_dump(exclude_unset=True).items():
        setattr(item, key, value)
    _commit(db)
    db.refresh(item)
    return item


@router.delete("/{item_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_category(item_id: uuid.UUID, db: DbSession) -> None:
    db.delete(_get_or_404(db, item_id))
    _commit(db)

