import com.example.shop.web.PageResponse;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.data.domain.Sort;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

import java.util.UUID;

@Service
@Transactional
public class BoxService {

    private final BoxRepository repository;

    public BoxService(BoxRepository repository) {
        this.repository = repository;
    }

    @Transactional(readOnly = true)
    public PageResponse<BoxResponse> list(int page, int size) {
        Page<Box> result = repository.findAll(PageRequest.of(page - 1, size, Sort.by(Sort.Direction.DESC, "createdAt")));
        return new PageResponse<>(result.map(BoxResponse::from).getContent(), page, size, result.getTotalElements(), result.getTotalPages());
    }

    @Transactional(readOnly = true)
    public BoxResponse get(UUID id) {
        return BoxResponse.from(find(id));
    }

    public BoxResponse create(CreateBoxRequest request) {
        Box box = new Box();
        box.setW(request.w());
        box.setH(request.h());
        return BoxResponse.from(repository.saveAndFlush(box));
    }

    public BoxResponse update(UUID id, UpdateBoxRequest request) {
        Box box = find(id);
        if (request.w() != null) box.setW(request.w());
        if (request.h() != null) box.setH(request.h());
        return BoxResponse.from(repository.saveAndFlush(box));
    }

    public void delete(UUID id) {
        repository.delete(find(id));
    }

    private Box find(UUID id) {
        return repository.findById(id).orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Box not found"));
    }
}

